add(fig('source-leakage-guard','The conservative source guard changes which question neighbors are compared. Upload links are lexical dependency proxies. Same-group and cross-group pair distributions reuse candidates and are not independent samples or agreement scores.'))
section('Question similarity weakly predicts answer wording')
add(f"Across {align['allDistinctUploadCandidatePairs']:,} distinct-upload candidate combinations, question and answer-gist lexical cosines have Spearman rank correlation {align['allPairRankCorrelation']:.3f}. Aggregating to upload-pair means changes the association to {align['uploadPairBalancedRankCorrelation']:.3f}. The change shows sensitivity to weighting and dependence, not a new independent sample.")
add(f"The {align['questionNeighborPairs']} question neighbors at cutoff 0.40 have mean answer-gist cosine {align['neighborAnswerCosine']['mean']:.3f}. Restricting them to different quarantine groups leaves {align['crossQuarantineNeighborPairs']} pairs with mean {align['crossQuarantineNeighborAnswerCosine']['mean']:.3f}. The {align['exactQuestionPairs']} pairs with identical normalized question wording still have mean answer-gist cosine {align['exactQuestionAnswerCosine']['mean']:.3f}. None of these scores codes whether answers agree. Quarantine groups are themselves defined by exact/high question similarity or multiple retrieval links; this selected-pool change cannot isolate a source-reuse effect.")
common=align.get('commonSupportStandardization')
if common:
 add(f"A second, explicitly exploratory comparison standardizes the within- and cross-quarantine answer means over question-cosine bins that contain both strata. The common-support pool contains {common['includedNeighborPairs']} pairs ({common['withinIncludedPairs']} within and {common['crossIncludedPairs']} cross), excluding {common['excludedNeighborPairs']} within-group pairs in high-similarity bins with no cross-group support. Pooled-bin weights applied identically to both strata give mean answer cosine {common['standardizedWithinMean']:.3f} versus {common['standardizedCrossMean']:.3f}, a difference of {common['standardizedWithinMinusCross']:.3f}. The directional within-group advantage is not disconfirmed by this sensitivity, but coarse bins leave prompt, length, topic and source-selection differences unresolved.")
 add(table(['Question-cosine band','Within pairs','Cross pairs','Within answer mean','Cross answer mean','Weight'],[[x['label'],x['withinPairs'],x['crossPairs'],f"{x['withinMeanAnswerCosine']:.3f}",f"{x['crossMeanAnswerCosine']:.3f}" if x['crossMeanAnswerCosine'] is not None else 'unavailable',f"{x['standardizationWeight']:.3f}" if x['standardizationWeight'] is not None else 'excluded'] for x in common['bins']],[.2,.12,.12,.17,.17,.12],'Question-similarity common support. Standardization uses identical pooled-bin weights only where both quarantine strata occur. Missing cross-stratum means are not zero. These dependent-pair summaries are neither agreement scores nor causal estimates.',wide=True))
 add(fig('question-cosine-common-support','Question-similarity support and standardized answer-gist contrast. Only three bins contain both strata: 93 retained pairs and 34 excluded higher-similarity within-group pairs. Identical pooled-bin weights yield descriptive means, with null unsupported comparisons. Group construction and remaining within-bin differences prevent a causal reuse or agreement interpretation.'))
add(fig('question-answer-alignment','Question and answer-gist lexical resemblance on source-addressable candidate pairs. Question and answer TF--IDF fits are separate. The quarantine contrast is a dependency sensitivity, not a causal source effect or a semantic agreement validation.'))
